private class OrderFacadeImpl(pricing: Pricing) extends OrderServiceGrpc.OrderService {
  override def placeOrder(req: PlaceOrderRequest): Future[OrderConfirmation] = {
    val order = Order.create(req.customer, req.lines)       // fine-grained model
    Future.successful(toConfirmation(order, pricing.price(order)))
  }
}
